export const REGION_PRESETS = {
  world: { x: 0, y: 0, w: 1000, h: 460, label: "全球" },
  apac: { x: 645, y: 74, w: 340, h: 245, label: "亚太" },
  eurasia: { x: 430, y: 36, w: 540, h: 276, label: "欧亚" },
  americas: { x: 68, y: 42, w: 360, h: 290, label: "美洲" },
};

function esc(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

export function projectLatLon(lat, lon) {
  const clampedLat = Math.max(LAT_MIN, Math.min(LAT_MAX, Number(lat) || 0));
  const clampedLon = Math.max(-180, Math.min(180, Number(lon) || 0));
  return {
    x: Math.round(((clampedLon + 180) / 360) * MAP_WIDTH * 10) / 10,
    y: Math.round(((LAT_MAX - clampedLat) / LAT_SPAN) * MAP_HEIGHT * 10) / 10,
  };
}

export function clampViewBox(vb) {
  const aspect = MAP_WIDTH / MAP_HEIGHT;
  const w = Math.max(140, Math.min(MAP_WIDTH, Number(vb.w) || MAP_WIDTH));
  const h = w / aspect;
  const x = Math.max(0, Math.min(MAP_WIDTH - w, Number(vb.x) || 0));
  const y = Math.max(0, Math.min(MAP_HEIGHT - h, Number(vb.y) || 0));
  return {
    x: Math.round(x * 10) / 10,
    y: Math.round(y * 10) / 10,
    w: Math.round(w * 10) / 10,
    h: Math.round(h * 10) / 10,
  };
}

export function computeFitViewBox(nodes) {
  const valid = (nodes || []).filter((n) => Number.isFinite(Number(n.lat)) && Number.isFinite(Number(n.lon)));
  if (!valid.length) return { ...REGION_PRESETS.world };
  // Focus auto-fit on active or explicitly declared devices so distant offline Tailscale peers don't squash active clusters
  const primary = valid.filter((n) => n.status !== "offline" || n.probeMode !== "tailscale-only");
  const source = primary.length >= 2 ? primary : valid;
  const pts = source
    .map((n) => projectLatLon(n.lat, n.lon));
  if (!pts.length) return { ...REGION_PRESETS.world };
  let minX = Infinity;
  let maxX = -Infinity;
  let minY = Infinity;
  let maxY = -Infinity;
  for (const pt of pts) {
    if (pt.x < minX) minX = pt.x;
    if (pt.x > maxX) maxX = pt.x;
    if (pt.y < minY) minY = pt.y;
    if (pt.y > maxY) maxY = pt.y;
  }
  const padX = Math.max(58, (maxX - minX) * 0.42);
  const padY = Math.max(38, (maxY - minY) * 0.48);
  const spanX = Math.max(220, maxX - minX + padX * 2);
  const spanY = Math.max(115, maxY - minY + padY * 2);
  const aspect = MAP_WIDTH / MAP_HEIGHT;
  let w = spanX;
  let h = w / aspect;
  if (h < spanY) {
    h = spanY;
    w = h * aspect;
  }
  const cx = (minX + maxX) / 2;
  const cy = (minY + maxY) / 2;
  return clampViewBox({ x: cx - w / 2, y: cy - h / 2, w, h });
}

function buildGraticule() {
  const lines = [];
  for (let lon = -150; lon <= 150; lon += 30) {
    const x = Math.round(((lon + 180) / 360) * MAP_WIDTH * 10) / 10;
    lines.push(`<line x1="${x}" y1="0" x2="${x}" y2="${MAP_HEIGHT}" class="${lon === 0 ? "wm-grat-major" : "wm-grat"}" />`);
  }
  for (let lat = -40; lat <= 60; lat += 20) {
    const y = Math.round(((LAT_MAX - lat) / LAT_SPAN) * MAP_HEIGHT * 10) / 10;
    lines.push(`<line x1="0" y1="${y}" x2="${MAP_WIDTH}" y2="${y}" class="${lat === 0 ? "wm-grat-major" : "wm-grat"}" />`);
  }
  return lines.join("");
}

const GRATICULE_SVG = buildGraticule();
const LAND_SVG = LAND_PATHS.map((d) => `<path d="${d}" class="wm-land" />`).join("");

function nodeTone(status) {
  const s = String(status || "offline").toLowerCase();
  if (s === "healthy" || s === "active" || s === "online") return "ok";
  if (s === "degraded" || s === "stale") return "warn";
  if (s === "standby") return "standby";
  return "err";
}

function layoutNodes(nodes, scale) {
  const base = (nodes || []).map((node) => {
    const anchor = projectLatLon(node.lat, node.lon);
    return { node, ax: anchor.x, ay: anchor.y, x: anchor.x, y: anchor.y, offset: false, labelPos: "bottom" };
  });

  // Group co-located nodes within threshold so markers & labels never collide
  const threshold = 16 * scale;
  const visited = new Set();
  for (let i = 0; i < base.length; i += 1) {
    if (visited.has(i)) continue;
    const cluster = [i];
    visited.add(i);
    for (let j = i + 1; j < base.length; j += 1) {
      if (visited.has(j)) continue;
      if (Math.hypot(base[i].ax - base[j].ax, base[i].ay - base[j].ay) < threshold) {
        cluster.push(j);
        visited.add(j);
      }
    }
    if (cluster.length > 1) {
      // Keep hub at center if present; fan others around it
      cluster.sort((a, b) => {
        const aHub = base[a].node.deviceType === "hub" ? 0 : 1;
        const bHub = base[b].node.deviceType === "hub" ? 0 : 1;
        return aHub - bHub;
      });
      const radius = Math.min(30, 17 + cluster.length * 3.0) * scale;
      const startIdx = base[cluster[0]].node.deviceType === "hub" ? 1 : 0;
      const orbiting = cluster.slice(startIdx);
      const angles = [-0.55, 0.55, 2.45, -2.45, 1.55, -1.55];
      orbiting.forEach((idx, k) => {
        const angle = angles[k % angles.length] + Math.floor(k / angles.length) * 0.4;
        const item = base[idx];
        item.x = Math.max(16, Math.min(MAP_WIDTH - 16, item.ax + Math.cos(angle) * radius));
        item.y = Math.max(16, Math.min(MAP_HEIGHT - 16, item.ay + Math.sin(angle) * radius));
        item.offset = true;
        item.labelPos = Math.sin(angle) < -0.15 ? "top" : "bottom";
      });
      if (startIdx === 1) {
        base[cluster[0]].labelPos = "top";
      }
    }
  }
  return base;
}

function estimateTextWidth(text, fontSize) {
  let units = 0;
  for (const ch of String(text || "")) {
    units += ch.charCodeAt(0) > 255 ? 1.18 : 0.72;
  }
  return units * fontSize;
}

function rectOverlapArea(a, b) {
  const ox = Math.max(0, Math.min(a.x2, b.x2) - Math.max(a.x1, b.x1));
  const oy = Math.max(0, Math.min(a.y2, b.y2) - Math.max(a.y1, b.y1));
  return ox * oy;
}

function placeNodeLabels(placed, { selectedNodeId, vb, scale, fontSize, subFontSize }) {
  const pad = 4 * scale;
  const occupied = placed.map((p) => ({
    x1: p.x - 9 * scale,
    y1: p.y - 9 * scale,
    x2: p.x + 9 * scale,
    y2: p.y + 9 * scale,
  }));

  const priorityScore = (item) => {
    if (item.node.id === selectedNodeId) return 0;
    if (item.node.deviceType === "hub") return 1;
    if (item.node.status === "healthy") return 2;
    if (item.node.status === "degraded") return 3;
    if (item.node.status === "standby") return 4;
    return 5;
  };

  const ordered = placed.map((item, index) => ({ item, index })).sort((a, b) => priorityScore(a.item) - priorityScore(b.item));
  const results = new Array(placed.length);

  const makeCandidates = (x, y, w, h, lineH, isTwoLine) => {
    const gx = 12 * scale;
    const gy = 13 * scale;
    const outerX = 24 * scale;
    const outerY = 24 * scale;
    const topBaseline = isTwoLine ? -(gy + lineH * 0.95) : -gy;
    const botBaseline = gy + fontSize * 0.85;
    const midBaseline = isTwoLine ? -fontSize * 0.1 : fontSize * 0.35;
    const rightEdge = vb.x + vb.w - 14 * scale;
    return [
      // Near ring (8 directions)
      { anchor: "start", lx: x + gx, ly: y + midBaseline, rx1: x + gx, ry1: y + midBaseline - fontSize * 0.9, rx2: x + gx + w, ry2: y + midBaseline - fontSize * 0.9 + h, leader: false },
      { anchor: "end", lx: x - gx, ly: y + midBaseline, rx1: x - gx - w, ry1: y + midBaseline - fontSize * 0.9, rx2: x - gx, ry2: y + midBaseline - fontSize * 0.9 + h, leader: false },
      { anchor: "middle", lx: x, ly: y + topBaseline, rx1: x - w / 2, ry1: y + topBaseline - fontSize * 0.9, rx2: x + w / 2, ry2: y + topBaseline - fontSize * 0.9 + h, leader: false },
      { anchor: "middle", lx: x, ly: y + botBaseline, rx1: x - w / 2, ry1: y + botBaseline - fontSize * 0.9, rx2: x + w / 2, ry2: y + botBaseline - fontSize * 0.9 + h, leader: false },
      { anchor: "start", lx: x + gx, ly: y + topBaseline, rx1: x + gx, ry1: y + topBaseline - fontSize * 0.9, rx2: x + gx + w, ry2: y + topBaseline - fontSize * 0.9 + h, leader: false },
      { anchor: "end", lx: x - gx, ly: y + topBaseline, rx1: x - gx - w, ry1: y + topBaseline - fontSize * 0.9, rx2: x - gx, ry2: y + topBaseline - fontSize * 0.9 + h, leader: false },
      { anchor: "start", lx: x + gx, ly: y + botBaseline, rx1: x + gx, ry1: y + botBaseline - fontSize * 0.9, rx2: x + gx + w, ry2: y + botBaseline - fontSize * 0.9 + h, leader: false },
      { anchor: "end", lx: x - gx, ly: y + botBaseline, rx1: x - gx - w, ry1: y + botBaseline - fontSize * 0.9, rx2: x - gx, ry2: y + botBaseline - fontSize * 0.9 + h, leader: false },
      // Outer ring with subtle leader line when dense
      { anchor: "start", lx: x + outerX, ly: y - outerY, rx1: x + outerX, ry1: y - outerY - fontSize * 0.9, rx2: x + outerX + w, ry2: y - outerY - fontSize * 0.9 + h, leader: true },
      { anchor: "end", lx: x - outerX, ly: y - outerY, rx1: x - outerX - w, ry1: y - outerY - fontSize * 0.9, rx2: x - outerX, ry2: y - outerY - fontSize * 0.9 + h, leader: true },
      { anchor: "start", lx: x + outerX, ly: y + outerY + fontSize * 0.5, rx1: x + outerX, ry1: y + outerY - fontSize * 0.4, rx2: x + outerX + w, ry2: y + outerY - fontSize * 0.4 + h, leader: true },
      { anchor: "end", lx: x - outerX, ly: y + outerY + fontSize * 0.5, rx1: x - outerX - w, ry1: y + outerY - fontSize * 0.4, rx2: x - outerX, ry2: y + outerY - fontSize * 0.4 + h, leader: true },
      { anchor: "middle", lx: x, ly: y - outerY * 1.45, rx1: x - w / 2, ry1: y - outerY * 1.45 - fontSize * 0.9, rx2: x + w / 2, ry2: y - outerY * 1.45 - fontSize * 0.9 + h, leader: true },
      { anchor: "middle", lx: x, ly: y + outerY * 1.65, rx1: x - w / 2, ry1: y + outerY * 1.65 - fontSize * 0.9, rx2: x + w / 2, ry2: y + outerY * 1.65 - fontSize * 0.9 + h, leader: true },
      // Viewport-clamped right-edge candidates (prevents coastal nodes from clipping at eastern border)
      ...(x + outerX + w > rightEdge ? [
        { anchor: "end", lx: rightEdge, ly: y + midBaseline, rx1: rightEdge - w, ry1: y + midBaseline - fontSize * 0.9, rx2: rightEdge, ry2: y + midBaseline - fontSize * 0.9 + h, leader: true },
        { anchor: "end", lx: rightEdge, ly: y - outerY * 1.15, rx1: rightEdge - w, ry1: y - outerY * 1.15 - fontSize * 0.9, rx2: rightEdge, ry2: y - outerY * 1.15 - fontSize * 0.9 + h, leader: true },
        { anchor: "end", lx: rightEdge, ly: y + outerY * 1.25, rx1: rightEdge - w, ry1: y + outerY * 1.25 - fontSize * 0.9, rx2: rightEdge, ry2: y + outerY * 1.25 - fontSize * 0.9 + h, leader: true },
        { anchor: "end", lx: rightEdge, ly: y - outerY * 2.1, rx1: rightEdge - w, ry1: y - outerY * 2.1 - fontSize * 0.9, rx2: rightEdge, ry2: y - outerY * 2.1 - fontSize * 0.9 + h, leader: true },
        { anchor: "end", lx: rightEdge, ly: y + outerY * 2.2, rx1: rightEdge - w, ry1: y + outerY * 2.2 - fontSize * 0.9, rx2: rightEdge, ry2: y + outerY * 2.2 - fontSize * 0.9 + h, leader: true },
      ] : []),
    ];
  };

  const evaluate = (cand) => {
    const rect = { x1: cand.rx1 - pad, y1: cand.ry1 - pad, x2: cand.rx2 + pad, y2: cand.ry2 + pad };
    const edgeMargin = 8 * scale;
    let penalty = cand.leader ? 18 : 0;
    if (rect.x1 < vb.x + edgeMargin) penalty += 50000 + (vb.x + edgeMargin - rect.x1) * 500;
    if (rect.x2 > vb.x + vb.w - edgeMargin) penalty += 50000 + (rect.x2 - (vb.x + vb.w - edgeMargin)) * 500;
    if (rect.y1 < vb.y + edgeMargin) penalty += 50000 + (vb.y + edgeMargin - rect.y1) * 500;
    if (rect.y2 > vb.y + vb.h - edgeMargin) penalty += 50000 + (rect.y2 - (vb.y + vb.h - edgeMargin)) * 500;
    let overlap = 0;
    for (const occ of occupied) {
      overlap += rectOverlapArea(rect, occ);
    }
    return { rect, overlap, score: overlap * 8 + penalty };
  };

  for (const { item, index } of ordered) {
    const { node, x, y } = item;
    const isSelected = node.id === selectedNodeId;
    const shortName = String(node.name || node.id).split(/[（(]/)[0].trim().slice(0, 18);
    const metricHint = node.battery?.percent != null
      ? `${Math.round(node.battery.percent)}%`
      : (node.cpu?.usagePct != null ? `CPU ${Math.round(node.cpu.usagePct)}%` : (node.region || ""));

    const lineGap = subFontSize * 1.28;
    const w2 = Math.max(estimateTextWidth(shortName, fontSize), estimateTextWidth(metricHint, subFontSize));
    const h2 = metricHint ? fontSize + lineGap + 2 * scale : fontSize + 2 * scale;
    const w1 = estimateTextWidth(shortName, fontSize);
    const h1 = fontSize + 2 * scale;

    let best = null;
    for (const cand of makeCandidates(x, y, w2, h2, lineGap, Boolean(metricHint))) {
      const ev = evaluate(cand);
      if (!best || ev.score < best.score) best = { ...cand, ...ev, showSub: Boolean(metricHint), shortName, metricHint };
    }

    // If two-line collides for non-selected node, retry single-line without sublabel
    if (best.overlap > 0 && !isSelected && metricHint) {
      for (const cand of makeCandidates(x, y, w1, h1, lineGap, false)) {
        const ev = evaluate(cand);
        if (ev.score < best.score) {
          best = { ...cand, ...ev, showSub: false, shortName, metricHint };
        }
      }
    }

    // If still heavily colliding for an offline non-selected peer in world view, hide inline label (still has tooltip + click)
    const hideLabel = !isSelected && node.status === "offline" && best.overlap > (w1 * h1 * 0.25);
    if (!hideLabel) {
      occupied.push(best.rect);
    }
    results[index] = { ...best, hideLabel, lineGap };
  }

  return results;
}

function renderMarkerGlyph(deviceType, scale) {
  const s = scale;
  if (deviceType === "hub") {
    return `
      <circle cx="0" cy="0" r="${(8.5 * s).toFixed(2)}" class="wm-node-halo" />
      <circle cx="0" cy="0" r="${(5.2 * s).toFixed(2)}" class="wm-node-core" />
      <circle cx="0" cy="0" r="${(2.0 * s).toFixed(2)}" class="wm-node-center" />
    `;
  }
  if (deviceType === "laptop") {
    const w = 9.6 * s;
    const h = 6.2 * s;
    return `
      <rect x="${(-w / 2).toFixed(2)}" y="${(-h / 2 - 0.8 * s).toFixed(2)}" width="${w.toFixed(2)}" height="${h.toFixed(2)}" rx="${(1.2 * s).toFixed(2)}" class="wm-node-core" />
      <line x1="${(-w * 0.68).toFixed(2)}" y1="${(h / 2 + 0.9 * s).toFixed(2)}" x2="${(w * 0.68).toFixed(2)}" y2="${(h / 2 + 0.9 * s).toFixed(2)}" stroke-width="${(1.6 * s).toFixed(2)}" class="wm-node-stroke" />
    `;
  }
  if (deviceType === "mobile") {
    const w = 6.2 * s;
    const h = 9.8 * s;
    return `
      <rect x="${(-w / 2).toFixed(2)}" y="${(-h / 2).toFixed(2)}" width="${w.toFixed(2)}" height="${h.toFixed(2)}" rx="${(1.5 * s).toFixed(2)}" class="wm-node-core" />
      <circle cx="0" cy="${(h * 0.3).toFixed(2)}" r="${(0.9 * s).toFixed(2)}" class="wm-node-center" />
    `;
  }
  // server / edge
  const r = 4.6 * s;
  return `
    <rect x="${(-r).toFixed(2)}" y="${(-r).toFixed(2)}" width="${(r * 2).toFixed(2)}" height="${(r * 2).toFixed(2)}" rx="${(1.6 * s).toFixed(2)}" class="wm-node-core" />
  `;
}

function buildDynamicLayersMarkup({ nodes = [], links = [], selectedNodeId = "", viewBox = REGION_PRESETS.world }) {
  const vb = clampViewBox(viewBox);
  const scale = Math.max(0.18, Math.min(1.05, vb.w / MAP_WIDTH));
  const placed = layoutNodes(nodes, scale);
  const byId = new Map(placed.map((p) => [p.node.id, p]));

  const arcSvg = (links || []).map((link) => {
    const a = byId.get(link.from);
    const b = byId.get(link.to);
    if (!a || !b) return "";
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const dist = Math.hypot(dx, dy);
    if (dist < 2) return "";
    const lift = Math.min(54 * scale, dist * 0.22);
    const mx = (a.x + b.x) / 2;
    const my = (a.y + b.y) / 2 - lift;
    const kind = String(link.kind || "direct").toLowerCase();
    const isHighlight = selectedNodeId && (link.from === selectedNodeId || link.to === selectedNodeId);
    const cls = [
      "wm-arc",
      `wm-arc-${kind}`,
      link.active ? "is-active" : "is-inactive",
      isHighlight ? "is-highlight" : "",
    ].filter(Boolean).join(" ");
    const strokeW = (isHighlight ? 2.1 : 1.35) * scale;
    const dash = kind === "relay" ? `${(4.5 * scale).toFixed(1)} ${(3.2 * scale).toFixed(1)}`
      : (kind === "checkin" || kind === "ssh" || kind === "backup" || kind === "external" ? `${(2.4 * scale).toFixed(1)} ${(3.0 * scale).toFixed(1)}` : "");
    const dAttr = `M${a.x.toFixed(1)} ${a.y.toFixed(1)} Q${mx.toFixed(1)} ${my.toFixed(1)} ${b.x.toFixed(1)} ${b.y.toFixed(1)}`;

    let rttTag = "";
    const rttNum = link.rttMs == null || link.rttMs === "" ? NaN : Number(link.rttMs);
    if (isHighlight && Number.isFinite(rttNum) && rttNum > 0 && dist > 72 * scale) {
      const lx = (0.25 * a.x + 0.5 * mx + 0.25 * b.x).toFixed(1);
      const ly = (0.25 * a.y + 0.5 * my + 0.25 * b.y - 4 * scale).toFixed(1);
      rttTag = `<text x="${lx}" y="${ly}" class="wm-arc-label" font-size="${(12.2 * scale).toFixed(1)}" text-anchor="middle">${esc(Math.round(rttNum))}ms</text>`;
    }

    return `<path d="${dAttr}" class="${cls}" stroke-width="${strokeW.toFixed(2)}"${dash ? ` stroke-dasharray="${dash}"` : ""} />${rttTag}`;
  }).join("");

  const leaderSvg = placed
    .filter((p) => p.offset)
    .map((p) => `<line x1="${p.ax.toFixed(1)}" y1="${p.ay.toFixed(1)}" x2="${p.x.toFixed(1)}" y2="${p.y.toFixed(1)}" class="wm-leader" stroke-width="${(0.9 * scale).toFixed(2)}" />`)
    .join("");

  const fontSize = 15.2 * scale;
  const subFontSize = 12.2 * scale;
  const labelPlacements = placeNodeLabels(placed, { selectedNodeId, vb, scale, fontSize, subFontSize });

  const labelLeaderSvg = placed.map((item, idx) => {
    const lp = labelPlacements[idx];
    if (!lp || lp.hideLabel || !lp.leader) return "";
    const tx = lp.anchor === "start" ? lp.lx - 3 * scale : (lp.anchor === "end" ? lp.lx + 3 * scale : lp.lx);
    const ty = lp.ly - fontSize * 0.3;
    return `<line x1="${item.x.toFixed(1)}" y1="${item.y.toFixed(1)}" x2="${tx.toFixed(1)}" y2="${ty.toFixed(1)}" class="wm-leader" stroke-width="${(0.85 * scale).toFixed(2)}" />`;
  }).join("");

  const nodeItems = placed.map((item, idx) => {
    const { node, x, y } = item;
    const lp = labelPlacements[idx];
    const tone = nodeTone(node.status);
    const isSelected = node.id === selectedNodeId;
    const titleText = `${node.name} (${node.region || "Tailnet"}) · ${node.status}${node.tailscaleIp ? " · " + node.tailscaleIp : ""}`;
    const relX = (lp.lx - x).toFixed(1);
    const relY = (lp.ly - y).toFixed(1);
    const relSubY = (lp.ly - y + lp.lineGap).toFixed(1);
    const inner = `
        <title>${esc(titleText)}</title>
        <circle cx="0" cy="0" r="${(15 * scale).toFixed(2)}" class="wm-hit-area" />
        ${isSelected ? `<circle cx="0" cy="0" r="${(12.2 * scale).toFixed(2)}" class="wm-select-ring" stroke-width="${(1.6 * scale).toFixed(2)}" />` : ""}
        ${renderMarkerGlyph(node.deviceType, scale)}
        ${lp.hideLabel ? "" : `<text x="${relX}" y="${relY}" text-anchor="${lp.anchor}" font-size="${fontSize.toFixed(1)}" class="wm-label">${esc(lp.shortName)}</text>`}
        ${!lp.hideLabel && lp.showSub && lp.metricHint ? `<text x="${relX}" y="${relSubY}" text-anchor="${lp.anchor}" font-size="${subFontSize.toFixed(1)}" class="wm-sublabel">${esc(lp.metricHint)}</text>` : ""}
    `;
    return {
      id: node.id,
      cls: `wm-node wm-tone-${tone}${isSelected ? " is-selected" : ""}`,
      transform: `translate(${x.toFixed(1)}, ${y.toFixed(1)})`,
      ariaLabel: titleText,
      inner,
    };
  });

  return { vb, arcSvg, leaderSvg: `${leaderSvg}${labelLeaderSvg}`, nodeItems };
}

export function renderWorldMapSvg({ nodes = [], links = [], selectedNodeId = "", viewBox = REGION_PRESETS.world }) {
  const { vb, arcSvg, leaderSvg, nodeItems } = buildDynamicLayersMarkup({ nodes, links, selectedNodeId, viewBox });
  const nodeSvg = nodeItems.map((n) => `
      <g class="${n.cls}"
         transform="${n.transform}"
         data-node-id="${esc(n.id)}"
         role="button"
         tabindex="0"
         aria-label="${esc(n.ariaLabel)}">
        ${n.inner}
      </g>
    `).join("");

  return `
    <svg class="wm-svg" viewBox="${vb.x} ${vb.y} ${vb.w} ${vb.h}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="全球多设备节点分布与链路拓扑地图">
      <rect x="0" y="0" width="${MAP_WIDTH}" height="${MAP_HEIGHT}" class="wm-ocean" />
      <g class="wm-graticule-layer">${GRATICULE_SVG}</g>
      <g class="wm-land-layer">${LAND_SVG}</g>
      <g class="wm-arc-layer">${arcSvg}</g>
      <g class="wm-leader-layer">${leaderSvg}</g>
      <g class="wm-node-layer">${nodeSvg}</g>
    </svg>
  `;
}

export function renderSparklineSvg(points, opts = {}) {
  const width = opts.width || 220;
  const height = opts.height || 52;
  const field = opts.field || "cpuPct";
  const unit = opts.unit ?? "%";
  const label = opts.label || field;
  const tone = opts.tone || "accent";

  const vals = (Array.isArray(points) ? points : [])
    .map((p) => (p && typeof p === "object" ? Number(p[field]) : Number(p)))
    .filter((v) => Number.isFinite(v));

  if (!vals.length) {
    return `
      <div class="spark-card">
        <div class="spark-head">
          <span class="spark-label">${esc(label)}</span>
          <span class="spark-val mono">暂无采样</span>
        </div>
        <svg class="spark-svg" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" aria-hidden="true">
          <line x1="0" y1="${height - 10}" x2="${width}" y2="${height - 10}" class="spark-grid" />
        </svg>
      </div>
    `;
  }

  const minVal = opts.min !== undefined ? opts.min : Math.min(...vals);
  const maxVal = opts.max !== undefined ? opts.max : Math.max(...vals, minVal + 1);
  const span = Math.max(1e-6, maxVal - minVal);
  const padY = 6;
  const plotH = height - padY * 2;
  const coords = vals.map((v, idx) => {
    const x = vals.length === 1 ? width : (idx / (vals.length - 1)) * width;
    const norm = Math.max(0, Math.min(1, (v - minVal) / span));
    const y = padY + (1 - norm) * plotH;
    return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
  });

  const linePoints = coords.map(([x, y]) => `${x},${y}`).join(" ");
  const areaPath = `M0,${height} L${coords.map(([x, y]) => `${x},${y}`).join(" L")} L${width},${height} Z`;
  const last = vals[vals.length - 1];
  const lastPt = coords[coords.length - 1];
  const formattedLast = Number.isInteger(last) ? `${last}${unit}` : `${last.toFixed(1)}${unit}`;

  return `
    <div class="spark-card">
      <div class="spark-head">
        <span class="spark-label">${esc(label)}</span>
        <span class="spark-val mono">${esc(formattedLast)}</span>
      </div>
      <svg class="spark-svg spark-tone-${esc(tone)}" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="${esc(label)} 趋势 ${esc(formattedLast)}">
        <line x1="0" y1="${(height / 2).toFixed(1)}" x2="${width}" y2="${(height / 2).toFixed(1)}" class="spark-grid" />
        <path d="${areaPath}" class="spark-area" />
        <polyline points="${linePoints}" fill="none" class="spark-line" />
        <circle cx="${lastPt[0]}" cy="${lastPt[1]}" r="3" class="spark-dot" />
      </svg>
    </div>
  `;
}

export function createWorldMapController(container, { onSelectNode } = {}) {
  let currentPreset = "fit";
  let viewBox = { ...REGION_PRESETS.world };
  let lastData = { nodes: [], links: [], selectedNodeId: "" };
  let dragging = null;
  let svgEl = null;
  let arcLayer = null;
  let leaderLayer = null;
  let nodeLayer = null;
  let lastArcSvg = null;
  let lastLeaderSvg = null;
  const nodeDomMap = new Map();

  function ensureBaseMounted() {
    if (!container || svgEl) return;
    container.innerHTML = `
      <svg class="wm-svg" viewBox="${viewBox.x} ${viewBox.y} ${viewBox.w} ${viewBox.h}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="全球多设备节点分布与链路拓扑地图">
        <rect x="0" y="0" width="${MAP_WIDTH}" height="${MAP_HEIGHT}" class="wm-ocean" />
        <g class="wm-graticule-layer">${GRATICULE_SVG}</g>
        <g class="wm-land-layer">${LAND_SVG}</g>
        <g class="wm-arc-layer"></g>
        <g class="wm-leader-layer"></g>
        <g class="wm-node-layer"></g>
      </svg>
    `;
    svgEl = container.querySelector("svg.wm-svg");
    arcLayer = svgEl?.querySelector(".wm-arc-layer");
    leaderLayer = svgEl?.querySelector(".wm-leader-layer");
    nodeLayer = svgEl?.querySelector(".wm-node-layer");
  }

  function render() {
    if (!container) return;
    ensureBaseMounted();
    if (!svgEl || !arcLayer || !leaderLayer || !nodeLayer) return;
    const { vb, arcSvg, leaderSvg, nodeItems } = buildDynamicLayersMarkup({
      nodes: lastData.nodes,
      links: lastData.links,
      selectedNodeId: lastData.selectedNodeId,
      viewBox,
    });

    const vbStr = `${vb.x} ${vb.y} ${vb.w} ${vb.h}`;
    if (svgEl.getAttribute("viewBox") !== vbStr) {
      svgEl.setAttribute("viewBox", vbStr);
    }
    if (arcSvg !== lastArcSvg) {
      arcLayer.innerHTML = arcSvg;
      lastArcSvg = arcSvg;
    }
    if (leaderSvg !== lastLeaderSvg) {
      leaderLayer.innerHTML = leaderSvg;
      lastLeaderSvg = leaderSvg;
    }

    const seenIds = new Set();
    const SVG_NS = "http://www.w3.org/2000/svg";
    for (const item of nodeItems) {
      seenIds.add(item.id);
      let entry = nodeDomMap.get(item.id);
      if (!entry) {
        const g = document.createElementNS(SVG_NS, "g");
        g.setAttribute("data-node-id", item.id);
        g.setAttribute("role", "button");
        g.setAttribute("tabindex", "0");
        nodeLayer.appendChild(g);
        entry = { g, cls: "", transform: "", ariaLabel: "", inner: "" };
        nodeDomMap.set(item.id, entry);
      }
      if (entry.cls !== item.cls) {
        entry.g.setAttribute("class", item.cls);
        entry.cls = item.cls;
      }
      if (entry.transform !== item.transform) {
        entry.g.setAttribute("transform", item.transform);
        entry.transform = item.transform;
      }
      if (entry.ariaLabel !== item.ariaLabel) {
        entry.g.setAttribute("aria-label", item.ariaLabel);
        entry.ariaLabel = item.ariaLabel;
      }
      if (entry.inner !== item.inner) {
        entry.g.innerHTML = item.inner;
        entry.inner = item.inner;
      }
    }
    for (const [id, entry] of nodeDomMap.entries()) {
      if (!seenIds.has(id)) {
        entry.g.remove();
        nodeDomMap.delete(id);
      }
    }
  }

  function setData({ nodes = [], links = [], selectedNodeId = "" }, { autoFit = false } = {}) {
    const firstRender = lastData.nodes.length === 0 && nodes.length > 0;
    lastData = { nodes, links, selectedNodeId };
    if ((firstRender || autoFit) && currentPreset === "fit") {
      viewBox = computeFitViewBox(nodes);
    }
    render();
  }

  function setRegion(presetKey) {
    currentPreset = presetKey;
    if (presetKey === "fit") {
      viewBox = computeFitViewBox(lastData.nodes);
    } else if (REGION_PRESETS[presetKey]) {
      viewBox = clampViewBox(REGION_PRESETS[presetKey]);
    }
    render();
  }

  function zoom(factor) {
    currentPreset = "custom";
    const cx = viewBox.x + viewBox.w / 2;
    const cy = viewBox.y + viewBox.h / 2;
    const nextW = viewBox.w * factor;
    const nextH = nextW / (MAP_WIDTH / MAP_HEIGHT);
    viewBox = clampViewBox({ x: cx - nextW / 2, y: cy - nextH / 2, w: nextW, h: nextH });
    render();
  }

  function focusNode(node) {
    if (!node || !Number.isFinite(Number(node.lat)) || !Number.isFinite(Number(node.lon))) return;
    const pt = projectLatLon(node.lat, node.lon);
    if (pt.x < viewBox.x + 20 || pt.x > viewBox.x + viewBox.w - 20 || pt.y < viewBox.y + 20 || pt.y > viewBox.y + viewBox.h - 20) {
      currentPreset = "custom";
      viewBox = clampViewBox({ x: pt.x - viewBox.w / 2, y: pt.y - viewBox.h / 2, w: viewBox.w, h: viewBox.h });
      render();
    }
  }

  if (container) {
    container.addEventListener("click", (ev) => {
      const nodeEl = ev.target.closest("[data-node-id]");
      if (nodeEl && typeof onSelectNode === "function") {
        onSelectNode(nodeEl.dataset.nodeId);
      }
    });

    container.addEventListener("keydown", (ev) => {
      if (ev.key !== "Enter" && ev.key !== " ") return;
      const nodeEl = ev.target.closest("[data-node-id]");
      if (nodeEl && typeof onSelectNode === "function") {
        ev.preventDefault();
        onSelectNode(nodeEl.dataset.nodeId);
      }
    });

    container.addEventListener("pointerdown", (ev) => {
      if (ev.button !== 0 || ev.target.closest("[data-node-id]")) return;
      const rect = container.getBoundingClientRect();
      if (!rect.width) return;
      dragging = { startX: ev.clientX, startY: ev.clientY, origVb: { ...viewBox }, width: rect.width, height: rect.height };
      container.classList.add("is-panning");
      container.setPointerCapture?.(ev.pointerId);
    });

    container.addEventListener("pointermove", (ev) => {
      if (!dragging) return;
      const dxPx = ev.clientX - dragging.startX;
      const dyPx = ev.clientY - dragging.startY;
      const scaleX = dragging.origVb.w / dragging.width;
      const scaleY = dragging.origVb.h / dragging.height;
      currentPreset = "custom";
      viewBox = clampViewBox({
        x: dragging.origVb.x - dxPx * scaleX,
        y: dragging.origVb.y - dyPx * scaleY,
        w: dragging.origVb.w,
        h: dragging.origVb.h,
      });
      const svg = container.querySelector("svg.wm-svg");
      if (svg) svg.setAttribute("viewBox", `${viewBox.x} ${viewBox.y} ${viewBox.w} ${viewBox.h}`);
    });

    const stopPan = () => {
      if (!dragging) return;
      dragging = null;
      container.classList.remove("is-panning");
    };
    container.addEventListener("pointerup", stopPan);
    container.addEventListener("pointercancel", stopPan);
  }

  return { setData, setRegion, zoom, focusNode, getViewBox: () => ({ ...viewBox }) };
}
